from abc import ABCMeta, abstractmethod

import six

from .connection_details import SshServiceDetails  # noqa: F401


@six.add_metaclass(ABCMeta)
class Switch(object):

    @abstractmethod
    def __init__(self, *args, **kwargs):
        pass


class DellS4048ONSwitch(Switch):
    def __init__(self, default_ssh_connection_details):
        # type: (SshServiceDetails) -> None
        """

        :param default_ssh_connection_details: SshServiceDetails class instance object
        """
        super(DellS4048ONSwitch, self).__init__()
        self.default_ssh_connection_details = default_ssh_connection_details

    def __taf_contract_ssh__(self):
        return self.default_ssh_connection_details.__taf_contract_ssh__()


